def shout(word):
    return word.upper() + "!"

def whisper(word):
    return word.lower() + "..."

def pick(mood):
    if mood == "loud":
        return shout
    return whisper

speak = pick("loud")
print(speak("Hello"))
print(pick("soft")("Hello"))

