sentinel_demo.py.src:
MISSING = sentinel("MISSING")

def lookup(cabinet, key, default=MISSING):
    if key in cabinet:
        return cabinet[key]
    if default is MISSING:
        return "no " + key + ", and no default given"
    return default

pets = {"cat": "Mog"}
print(lookup(pets, "cat"))
print(lookup(pets, "dog", None))
print(lookup(pets, "dog"))
print(MISSING)

